function talH(h){const xt=xTal(h).filter(t=>h.lv>=t[0]&&(t[1]!=='awk'||h.br2!=null)).map(t=>t[1]);const C=CHR[h.key];if(!C)return [...talOf(cand(h.key).cls,h.lv),...xt];const o=C.tal.filter(t=>h.lv>=t[0]).map(t=>t[1]);if(h.br!=null&&h.br2!=null&&h.lv>=20)o.push(h.key+'_b2_'+(h.br*2+h.br2));if(h.tr3)o.push('tr3_'+h.key);return [...o,...xt]}
function talList(h){const C=CHR[h.key];return [...(C?C.tal:TAL[cand(h.key).cls]),...xTal(h)]}
function fxOf(tal){const o={};tal.forEach(id=>{const v=PV[id];if(v)for(const k in v){if(Array.isArray(v[k]))o[k]=[...(o[k]||[]),...v[k]];else o[k]=(o[k]||0)+v[k]}});return o}
function baseOf(key){const c=CLS[cand(key).cls];const C=CHR[key];let b=c.base.map(x=>x.slice());if(C){b=b.map(([k,l])=>[k===C.rep?C.sk:k===C.rep2&&C.sk2?C.sk2:k,k===C.rep?1:l]);b.push([C.sk15,15])}return b}
function akOf(h){const b='h_'+h.key;if(h.tr3&&HAS.has(b+'_C'))return b+'_C';if(h.br!=null){const a=b+'_'+'AB'[h.br];if(h.br2!=null&&HAS.has(a+(h.br2+1)))return a+(h.br2+1);if(HAS.has(a))return a}return b}
