function mkSet(id,slot,T){const X=SETS[id];let it;if(X.parts){const sl=slot||pick(Object.keys(X.parts));it=genItem(id==='wanx'?X.t:Math.max(X.t,storyTier()),200,sl);it.atk=Math.round(it.atk*1.1);it.def=Math.round(it.def*1.1);if(sl==='o'&&it.ok!=='tome'){delete it.blk;it.def=0;it.at={int:X.t};it.ok='tome';it.pw=+(.04*X.t).toFixed(2)}it.r=Math.max(it.r,3);it.n=X.parts[sl]}else{const sl=slot||pick(['s','g','f','r','n']);it=genItem(T||1,75,sl);it.r=Math.max(it.r,1);it.n=X.n+'・'+it.n}it.set=id;return it}
function ownedParts(id){const all=[...S.bag,...S.heroes.flatMap(h=>Object.values(h.eq||{})),...(RUN?RUN.loot.gear:[])];return new Set(all.filter(it=>it&&it.set===id).map(it=>it.s))}
function setCount(eq){const c={};const seen={};for(const s of SLOTS){const it=eq[s];if(it&&it.set&&SETS[it.set]){const key=it.set+'|'+it.n;if(seen[key])continue;seen[key]=1;c[it.set]=(c[it.set]||0)+1}}return c}
function setLine(eq){const c=setCount(eq);const ks=Object.keys(c);if(!ks.length)return '';return '<div class="q">'+ks.map(k=>{const X=SETS[k],n=c[k],full=X.b6?6:X.parts?4:2;return `<b style="color:#7fe0c9">【${X.n}】${n}/${full}</b><br><span class="note" style="${n>=2?'color:#bfeee2':''}">2件：${X.b2}</span>${X.parts?`<br><span class="note" style="${n>=4?'color:#bfeee2':''}">4件：${X.b4}</span>`:''}${X.b6?`<br><span class="note" style="${n>=6?'color:#bfeee2':''}">6件：${X.b6}</span>`:''}`}).join('<br>')+'</div>'}
