function mkUQ(id){const U=UQ[id];const sty=U.story||id.startsWith('kq_')||id==='fox';const it=genItem(sty?storyTier():Math.max(U.t,storyTier()),sty?0:200,U.s);if(sty)it.story=1;it.r=U.ep?4:3;if(U.ep){it.atk=Math.round(it.atk*1.25);it.def=Math.round(it.def*1.25);for(const k in it.at)it.at[k]+=2}it.n=U.n;it.uq=id;if(U.s==='o'){delete it.blk;it.def=0;it.at={int:U.t};it.ok='tome';it.pw=+(.04*U.t).toFixed(2)}if(id==='throat')ATR.forEach(k=>it.at[k]=(it.at[k]||0)+3);if(id==='weight')it.at.int=(it.at.int||0)+2;return it}
function ownUQ(id){const all=[...S.bag,...(S.unid||[]),...S.heroes.flatMap(h=>Object.values(h.eq||{})),...(RUN?RUN.loot.gear:[])];return all.some(it=>it&&it.uq===id)}
