const XN={crit:'暴擊',crr:'防暴擊',luk:'幸運',drop:'掉寶',pres:'物抗',mres:'魔抗',ls:'吸血',acc:'命中',thn:'反傷',cres:'控制抗性',ares:'異常抗性'},XR={crit:.02,crr:.025,luk:.03,drop:.04,pres:.02,mres:.02,ls:.012,acc:.02,thn:.025,cres:.03,ares:.03};
