function gearDesc(it,sh){const p=[];if(it.atk)p.push('攻擊 +'+it.atk);if(it.def)p.push('防禦 +'+it.def);for(const k of ATR)if(it.at[k])p.push(ATN[k]+(it.at[k]>0?' +':' ')+it.at[k]);if(it.blk)p.push('格擋 '+Math.round(it.blk*100)+'%');if(it.pw)p.push('技能 +'+Math.round(it.pw*100)+'%');if(it.wk==='2h')p.push('佔用副手');if(it.wk==='dual')p.push('普攻 50% 打兩下・佔用副手');if(it.x)for(const k in XN)if(it.x[k])p.push(XN[k]+' +'+Number((it.x[k]*100).toFixed(2))+'%');let t=p.join('・');if(it.uq&&UQ[it.uq]){t+=`<br><span class="uqd">✦ ${UQ[it.uq].d}</span>`;if(UQ[it.uq].lore&&!sh)t+=`<br><span class="lore">${UQ[it.uq].lore}</span>`}if(it.tem&&TEMPER[it.tem])t+=`<br><span class="uqd">◈ 淬煉・${TEMPER[it.tem][0]}：${TEMPER[it.tem][1]}</span>`;if(it.mem&&!sh)t+=`<br><span class="lore">${esc(it.mem)}</span>`;if(it.set&&SETS[it.set]){const X=SETS[it.set];t+=sh?`<br><span class="setd">【${X.n}】套裝</span>`:`<br><span class="setd">【${X.n}】2件：${X.b2}${X.parts?'／4件：'+X.b4:''}</span>`}return t}
const gcls=it=>it.uq?5:it.set?6:it.r+1;
let gearName=it=>`<b class="r${it.uq&&UQ[it.uq]&&UQ[it.uq].ep?8:it.uq&&UQ[it.uq]&&UQ[it.uq].leg?7:gcls(it)}">${it.e>=10?'不褪的':''}${esc(it.n)}${it.e?(it.e>=5?' <span class="enh">+'+it.e+'</span>':' +'+it.e):''}</b> <span class="tag">${SLOTN[it.s]}${typeTag(it)?'・'+typeTag(it):''}・${it.uq?(UQ[it.uq]&&UQ[it.uq].ep?'史詩':UQ[it.uq]&&UQ[it.uq].leg?'傳說':'特色'):it.set?'套裝':RAR[it.r]}</span>`;
const gearVal=it=>Math.round((it.t*10+it.r*12)*.6*(it.uq?2:it.set?1.5:1))+(it.e||0)*8;
function fixItem(o){if(!o)return null;if(o.s==='c')o.s='r';if(!ITYPES.includes(o.s))return null;const it={u:n0(o.u,0),s:o.s,t:Math.min(10,Math.max(1,n0(o.t,1))),r:Math.min(4,n0(o.r,0)),n:String(o.n||'舊物').slice(0,16),atk:Math.min(2000,n0(o.atk,0)),def:Math.min(1500,n0(o.def,0)),at:{}};for(const k of ATR)if(o.at&&o.at[k])it.at[k]=Math.max(-5,Math.min(120,Math.round(+o.at[k]||0)));if(WTN[o.wt])it.wt=o.wt;if(WKN[o.wk])it.wk=o.wk;if(OKN[o.ok])it.ok=o.ok;if(o.blk)it.blk=Math.min(.3,+o.blk||0);if(o.pw)it.pw=Math.min(.3,+o.pw||0);if(o.x&&typeof o.x==='object'){it.x={};for(const k in XN)if(o.x[k])it.x[k]=Math.min(.5,Math.max(0,+o.x[k]||0))}if(o.uq&&UQ[o.uq]){it.uq=o.uq;it.n=UQ[o.uq].n}if(o.set&&SETS[o.set])it.set=o.set;const e=Math.min(10,n0(o.e,0));if(e){it.e=e;if(o.e7)it.e7=1;if(o.b)it.b={atk:Math.min(2000,n0(o.b.atk,0)),def:Math.min(1500,n0(o.b.def,0))};if(ATR.includes(o.ea))it.ea=o.ea;if(XN[o.e5k]){it.e5k=o.e5k;it.e5v=Math.min(.3,+o.e5v||0)}if(XN[o.e8k]){it.e8k=o.e8k;it.e8v=Math.min(.3,+o.e8v||0)}if(XN[o.e10k]){it.e10k=o.e10k;it.e10v=Math.min(.4,+o.e10v||0)}}if(o.story)it.story=1;if(typeof o.mem==='string'&&ENH_MEM.includes(o.mem))it.mem=o.mem;if(['wick2','clapper','crowEye','rightLine','unsigned'].includes(o.tem))it.tem=o.tem;return it}
