const EVB={"gate": {"in": "地址之門前，成百上千頁泛黃的舊戶籍冊從地面和穹頂同時掀開。紙頁之間，無數張看不見臉的嘴整齊列隊，幾十道男女老少重疊的嗓音一起翻開了點名簿：「一戶一冊，對不上姓氏的人，不準過這扇門！」", "atk": "合唱體齊聲唱出一段走調卻震耳欲聾的點名曲。漫天的戶籍殘頁像刀片一樣捲過來，想把你們胸口名牌上的筆畫硬生生拆開，重組進牠們錯亂的家譜裡！", "hurt": "你們撕開了合唱體最外層的空白書皮。原本整齊的點名聲一下子亂了拍子，好幾道聲音開始互相爭吵：「你唱錯行了！那個偏旁不是我們家的！」", "down": "最中央那本厚重的總戶籍冊被一擊劈開書脊，幾十道嗓音同時停在最後一個音節上，發出一聲如釋重負的長嘆：「……點名完畢，全數放行。」漫天紙頁像雪一樣，安安靜靜地落回地面。", "end": "散落的戶籍紙頁在門前鋪成一條白路，再也沒有聲音攔著你們。"}, "tkeeper": {"in": "沉重的石盤摩擦聲在迴廊裡迴盪。一尊背著巨大青石日晷的佝僂怪影慢慢轉過身。牠背上的銅晷針正逆著光影瘋狂倒轉，連周圍飄落的灰塵，都被拽著往天上飛！", "atk": "守時者猛然壓低背上的日晷，倒轉的晷針投出一道冰冷的扇形暗影橫掃全場。被影子掃過的傷口和步伐，被硬生生往回拖！", "hurt": "重擊在日晷盤面上砸出一道貫穿子午線的裂痕。倒走的銅針卡在裂縫裡劇烈顫抖，守時者發出齒輪崩牙一樣的刺耳嘶鳴。", "down": "倒轉的銅晷針被硬生生折斷，背上的石盤轟然碎成十二塊。牠伸手想去抓地上漏走的影子，卻連同自己的身體一起，化成了定格的石粉。", "end": "碎掉的日晷不再倒轉，迴廊裡停住的空氣，重新開始往前流。"}, "emptypost": {"in": "迴廊中央，筆直地站著一套深綠色的舊郵差制服。領口上方空蕩蕩的，沒有頭；袖管裡也沒有手。胸口原本縫著名字的布條，被撕得只剩幾根白線頭。只有肩上那只空帆布郵袋，被看不見的骨架撐得鼓鼓的。", "atk": "空制服邁開無聲的步子，兩隻空袖管像長鞭一樣抽過來，同時把肩上沉重的郵袋掄圓了當頭罩下——想把活人也當成漏寄的信，塞進袋底！", "hurt": "刀刃劃開了制服的前襟。裡面沒有流出一滴血，只有一團團褪了色的舊郵戳印記和冷風從破口漏出來。整套制服晃了兩晃，像被風吹皺的空布袋。", "down": "最後一擊挑斷了掛在空肩膀上的郵袋皮扣。少了郵袋的重量，那套硬撐著站著的制服一下子沒了力氣，輕飄飄地垂落在地，像一件終於被人換下來、疊好的舊衣裳。", "end": "地上只剩一套乾乾淨淨、沒有主人的空制服。你們把散在旁邊的郵戳收起來，繞過那件衣服，繼續往前走。"}};for(const k in EVB)FOES[k].ev=EVB[k];
const MPRE={"tkeeper": ["「咔噠……咔噠……你們走得太快了。外頭的日頭還沒落山，這裡的昨天還沒過完。」", "「把你們身上的時辰交出來……跟這座日晷一起，退回出門之前！」"], "emptypost": ["「……名牌沒了，但郵袋還背在肩上。沒人接班，這趟班次就不算跑完。」", "「別擋著郵路……把你們手裡還沒投出去的信，統統放進袋子裡來。」"]};
const DOMT={"giant": {"in": "整座石室熱得讓人喘不過氣。比記憶中大上好幾倍的燭苔巨人幾乎塞滿了穹頂，身上的古根和石骨早就被滾燙的白蠟澆鑄在一起，連呼吸都帶著岩石融化的焦味。", "crack": "巨人的外層石殼轟然裂開。裡面沒有血肉，而是猛地爆開成百上千盞密密麻麻、燒得慘白的石骨燭火，刺眼的光和熱浪一下子吞沒了整片視野！", "down": "最後一盞主心燭熄滅了。沸騰的蠟海瞬間冷卻，那尊塞滿房間的巨人一寸一寸化成冰冷的灰白蠟雕，再也沒有半點溫度。"}, "badger": {"in": "回憶裡的靜鐘長不再只是守著一口小鐘。牠龐大的身體和整座第六層的青銅巨鐘融成了一體，四周安靜得連你們的心跳聲，都被牠胸口的黑洞吸了進去。", "crack": "巨鐘表面裂開一道橫過胸膛的縫。裡面沒有鐘槌，而是湧出無數條由「被抹去的聲音」凝成的灰白紙舌，無聲卻狂暴地朝四周震盪開來！", "down": "裂開的巨鐘發出一聲誰也聽不見的悶響，紙舌全部縮回鐘腹。牠慢慢趴伏下來，閉上眼睛，把整間石室還給了真正的安靜。"}, "bird": {"in": "沒有單獨的一隻鳥。整間回憶房的天花板和牆壁，全被層層疊疊的空白戶籍頁鋪滿。千頁紙鴉在紙海中央張開遮天的雙翼，每一片羽毛上，都睜著一隻墨點做成的眼睛。", "crack": "紙鴉的胸口被撕開一道大口子。裡面沒有骨頭，而是炸開一場由上萬片鋒利折紙組成的黑色暴風雪，無數張空白紙頁瘋狂地想拓下你們的臉！", "down": "撐著鴉群核心的那枚主封蠟印應聲碎裂。遮天的紙海失去了風，像一場下完的灰雪，靜靜鋪滿石板。"}, "tkeeper": {"in": "回憶房裡所有的影子都被拉得筆直又怪異。異變的守時者背上不再只有一面日晷，而是層層疊疊背著幾十面指針方向全不一樣的黃銅鐘盤，齒輪咬合的巨響震得人站都站不穩。", "crack": "最外層的石晷盤轟然崩裂，守時者胸膛裡探出無數根燒得通紅的倒轉發條和秒針。整間屋子的時間開始一秒往前、一秒往後地瘋狂撕扯！", "down": "最後一根主發條徹底繃斷，幾十面鐘盤的指針同時停在同一條直線上。守時者龐大的身體，在刺耳的報時聲中一寸寸瓦解。"}, "emptypost": {"in": "回憶房裡整整齊齊地懸空站著一整排沒有頭、沒有手的深綠郵差制服。最前面那套背後，拖著一只大得像房子、被無數死信撐到變形的帆布郵袋。", "crack": "主制服的前胸和後背同時裂開，巨型郵袋的拉鍊崩斷，無數條由紅色退件封條和生鏽郵筒鎖鏈擰成的巨手，從領口和袖管裡狂湧而出！", "down": "最後一條鎖鏈被斬斷，那一整排懸空的制服像斷了線一樣輕輕落回地面，整整齊齊地疊在一起，再也沒有動靜。"}, "wusign": {"in": "無簽高坐在萬千鐵皮信箱砌成的審判台頂端。驛站長袍化成了密密麻麻的黑色退件公文，胸口的鐵郵箱裂成一張巨大的鉛字格，手裡那枚「查無此人」的黑鐵大印，重得壓彎了空間。", "crack": "無簽胸口的鐵郵箱轟然炸開，成千上萬枚滾燙的鉛字塊和黑泥印章在半空中聚成好幾條巨大的金屬手臂，對著整間房間無差別地連續蓋下註銷黑印！", "down": "黑鐵大印從中間裂成兩半，漫天的鉛字塊叮叮噹噹地落回信箱格裡。無簽高大的身體化成一疊終於蓋上「結案」章的泛黃卷宗，安安靜靜地散在台階上。"}};
