function afterLine(k){S.aft=S.aft||{};const pool=[];for(const b in AFTER){if(!(S.inv[b]&&S.inv[b].st==='done'))continue;AFTER[b].forEach((x,i)=>{const id=b+'_'+i;if(x[0]===k&&!S.aft[id])pool.push([id,x])})}
 if(!pool.length||Math.random()>.45)return null;const [id,x]=pick(pool);S.aft[id]=1;const got=x[3]?x[3]():'';
 const tot=AFTER[id.split('_')[0]].length,seen=Object.keys(S.aft).filter(z=>z.startsWith(id.split('_')[0])).length;
 return {id,line:x[2],act:x[1],after:[{r:(got?got+'\n':'')+'後話 '+seen+'/'+tot+'「'+INV[id.split('_')[0]].t+'」'}]}}
