const tuCost=it=>({pts:60*it.t,ink:it.t>=3?3:2,seal:it.t>=4?3:0,bm:it.t>=3?1:0});
function tuCostTxt(it){const c=tuCost(it);return `積分 ${c.pts}、墨 ${c.ink}${c.seal?'、退件印泥 '+c.seal:''}${c.bm?'、任一種領主素材 1':''}、${materialText156(upgradeCost156(it))}`}
function apprUp(u){const f=findIt(u);if(!f)return apprMenu();const it=f.it;if(it.t>=tierCap())return apprMenu();const c=tuCost(it);const extra=upgradeCost156(it);if(!canMaterials156(extra))return toast("升階素材不足："+materialText156(extra));const bm=bmBest();
 if(S.pts<c.pts||S.mats.ink<c.ink||(S.mats.seal||0)<c.seal||(c.bm&&!bm))return toast('材料不夠。');
 payMaterials156(extra);S.pts-=c.pts;S.mats.ink-=c.ink;if(c.seal)S.mats.seal-=c.seal;if(c.bm)S.bmat[bm]--;
 const r=TUPR[it.t]||1.12,e=it.e||0;if(e)enhApply(it,0);it.atk=Math.round(it.atk*r);it.def=Math.round(it.def*r);for(const k in it.at)it.at[k]=Math.max(it.at[k]+1,Math.round(it.at[k]*r));if(it.x)for(const k in it.x)it.x[k]=+(it.x[k]*(it.t+1)/it.t).toFixed(3);if(it.pw)it.pw=+(it.pw*(it.t+1)/it.t).toFixed(2);if(it.blk)it.blk=+(it.blk*1.1).toFixed(3);it.t++;delete it.b;if(e)enhApply(it,e);
 save();res();sfx('chime');modal(twHead('appr')+`<p>鏡片後面的人把它放進秤盤，壓上一枚你看不懂的砝碼。秤盤沉下去，又浮起來。</p><p style="font-size:16px">${gearName(it)}　<span class="note">→ 第 ${it.t} 階</span></p><p class="note">${gearDesc(it)}</p><div class="row"><button class="btn primary" onclick="apprMenu()">好</button></div>`)}
function apprRe(u){const f=findIt(u);if(!f)return apprMenu();const it=f.it;const ks=Object.keys(it.x||{});if(!ks.length)return apprMenu();if(S.pts<20*it.t||S.mats.ink<1)return toast('積分或書霧墨不夠。');S.pts-=20*it.t;S.mats.ink-=1;
 const old=pick(ks),pool=Object.keys(XN).filter(k=>!ks.includes(k));const nk=pick(pool.length?pool:Object.keys(XN));const keep5=it.e5k===old;delete it.x[old];it.x[nk]=+((it.x[nk]||0)+XR[nk]*(rnd(5,10)/10)*it.t).toFixed(3);if(keep5){it.e5k=nk;it.e5v=it.x[nk]}
 save();res();sfx('chime');modal(twHead('appr')+`<p>他用鑷子夾起一條看不見的線，換了一條上去。</p><p>${gearName(it)}<br><span class="note">${XN[old]} → <b>${XN[nk]} +${Math.round(it.x[nk]*100)}%</b></span></p><div class="row"><button class="btn" onclick="apprRe(${it.u})">再洗一次</button><button class="btn primary" onclick="apprMenu()">好</button></div>`)}
function today(){const d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}
function dailyGet(){if(!S.daily||S.daily.date!==today()){const q=newQuest();q.need=Math.max(q.need,q.type==='floor'?q.need:q.need+1);q.pts=Math.round(q.pts*2);S.daily={date:today(),q,rc:rnd(2,4),claimed:false}}return S.daily}
function dailyMenu(){const D=dailyGet(),q=D.q,pg=qProg(q),ok=pg>=q.need;
 modal(twHead('daily',`<p class="note">二樓的任務層。你把徽章放上櫃台，羽紋轉了半圈，浮出一行沒有署名的字。</p>`)+`<div class="q"><b>今日的未署名委託</b><br>${qTitle(q)}　<span class="note">${pg}／${q.need}</span><br><span class="note">報酬：積分 ${q.pts}、渡鴉幣 ${D.rc}（另有每日委託首領獎勵）</span></div>${D.claimed?'<p class="note">今天的委託已經完成了。明天徽章會再浮出新的一行。</p>':''}<div class="row">${!D.claimed&&ok?'<button class="btn primary" onclick="dailyClaim()">交付</button>':''}<button class="btn ${!D.claimed&&ok?'':'primary'}" onclick="closeModal()">離開</button></div>`)}
function dailyClaim(){const D=dailyGet();if(D.claimed||qProg(D.q)<D.q.need)return dailyMenu();D.claimed=true;S.pts+=D.q.pts;coinCredit210(D.rc);const ex=[];if(Math.random()<.1)ex.push(planGet());if(Math.random()<.15){const g=storyGet();if(g)ex.push(g)}D.ex=ex;save();res();sfx('chime');
 modal(twHead('daily')+`<p>櫃台後面的人收下證明，在徽章邊緣記下幾道羽紋。委託酬勞會記入今日渡鴉幣收入。</p><p class="note">得到積分 ${D.q.pts}、渡鴉幣 ${D.rc}（另有每日委託首領獎勵）（現在 ${S.ravc} 枚）${(D.ex||[]).length?'<br>還有：'+D.ex.join('、'):''}</p><div class="row"><button class="btn primary" onclick="closeModal();town()">好</button></div>`)}
const EXG=[['seal','退件印泥 ×2',3,()=>{S.mats.seal=(S.mats.seal||0)+2}],['wax','燭淚蠟 ×3',2,()=>{S.mats.wax+=3}],['ink','書霧墨 ×4',2,()=>{S.mats.ink+=4}],['yq','混亂券 ×5',2,()=>{S.yq=(S.yq||0)+5}],['bm','隨機一種領主素材',6,()=>{const k=pick(Object.values(BOSSMAT).map(x=>x[0]));S.bmat=S.bmat||{};S.bmat[k]=(S.bmat[k]||0)+1;return BOSSMAT[Object.keys(BOSSMAT).find(b=>BOSSMAT[b][0]===k)][1]}],['box','被封起來的東西',12,()=>{const pool=LEG_IDS.filter(k=>!ownUQ(k));const id=pick(pool.length?pool:LEG_IDS);const it=mkUQ(id);it._n=it.n;it.n='被封起來的東西';it._sealed=1;S.unid=(S.unid||[]).concat([it]);return '去鑑定館打開它'}]];
EXG.push(['pack','升階材料包（印泥 5、墨 6、領主素材 1）',8,()=>{S.mats.seal=(S.mats.seal||0)+5;S.mats.ink+=6;const k=pick(Object.values(BOSSMAT).map(x=>x[0]));S.bmat=S.bmat||{};S.bmat[k]=(S.bmat[k]||0)+1}],['sure','必成符（下一次強化一定成功）',15,()=>{S.sure=(S.sure||0)+1;return '現在有 '+S.sure+' 張'}],['leg','指定一件傳說裝備',25,null],['ep','一件史詩裝備（隨機）',45,()=>{const pool=EP_IDS.filter(k=>!ownUQ(k));if(!pool.length){S.jx212+=exPrice(EXG.findIndex(g=>g[0]==='ep'));return '你已經收齊了，硬幣退回來了'}const it=mkUQ(pick(pool));S.bag.push(it);return it.n}]);
const DESIRE=['櫃台後面的人好像很想要它。','今天沒什麼人問這個。','有人剛剛為它吵了一架。','它的價錢，跟你多想要它有關。','櫃台後面的人盯著你的徽章看了很久。'];
function exchPrices(){if(!S.exch||S.exch.r!==S.returns||S.exch.f.length!==EXG.length)S.exch={r:S.returns,f:EXG.map(()=>+(0.5+Math.random()*1.5).toFixed(2)),l:EXG.map(()=>pick(DESIRE))};return S.exch}
