function genFloor(){const W=7,H=11,f=RUN.floor,T=tierOf(f);const g=Array.from({length:H},()=>Array(W).fill('#'));
 let x=3,y=H-2;g[y][x]='U';let n=1;const target=26+Math.min(10,f);let guard=0;
 while(n<target&&guard++<5000){const r=Math.random();const [dx,dy]=r<.34?[0,-1]:r<.5?[0,1]:r<.75?[-1,0]:[1,0];const nx=x+dx,ny=y+dy;if(nx<1||ny<1||nx>W-2||ny>H-2)continue;x=nx;y=ny;if(g[y][x]==='#'){g[y][x]='.';n++}}
 const sx=3,sy=H-2;const dist={[sx+','+sy]:0};const q=[[sx,sy]];while(q.length){const [cx,cy]=q.shift();for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=cx+dx,ny=cy+dy,k=nx+','+ny;if(g[ny]&&g[ny][nx]&&g[ny][nx]!=='#'&&dist[k]==null){dist[k]=dist[cx+','+cy]+1;q.push([nx,ny])}}}
 const cells=Object.entries(dist).filter(([k,d])=>d>=2).map(([k,d])=>[...k.split(',').map(Number),d]).sort((a,b)=>b[2]-a[2]);
 const far=cells.shift();const isBoss=f===T.to;g[far[1]][far[0]]=isBoss||(MINI[f]&&!RUN.abyss)?'B':'D';
 const free=shuffle(cells);const mon={};const put=(ch,cnt)=>{for(let i=0;i<cnt&&free.length;i++){const [cx,cy]=free.pop();g[cy][cx]=ch;if(ch==='M')mon[cx+','+cy]={k:EXF[tierN(f)]&&!RUN.mem&&Math.random()<.2?pick(EXF[tierN(f)]):pick(T.foes),elite:f>1&&Math.random()<(f>=10?.3:.18)}}};
 S.encCD=(S.encCD||0)+1;RUN.encDone=0;if(!RUN.mem&&S.encCD>=1&&(S.encCD>=4||Math.random()<Math.min(.85,.35+(S.encCD-1)*.15+(S.weather==='fog'?.15:0))))put('Q',1);
 put('M',Math.min(9,4+Math.floor(f/2)+(RUN.party.some(q=>hasU(q,'st_banner'))?1:0)));if(f>=3&&!RUN.mem&&!RUN.abyss&&Math.random()<(f>=10?.35:.22)){const ks=Object.keys(mon).filter(k=>!mon[k].hidden);if(ks.length){const m=mon[pick(ks)];m.chief=1;m.elite=false}}RUN.intr=0;if(f>=2&&!isBoss&&Math.random()<(f>=7?.8:.6)){const ks=Object.keys(mon);if(ks.length){if(S.story>=3&&Math.random()<.12){mon[pick(ks)]={k:pick(YC_ALL),elite:1,hidden:1,intr:1,up:1,yy:1,lost:1}}else{const pool=[...(RUN.portal?[]:['chorus','chorus']),'foxlamp','rootkin'];{const chief=Math.random()<(f>=10?.2:.12);mon[pick(ks)]={k:pick(pool),elite:!chief,chief:chief?1:0,hidden:1,intr:1,up:rnd(1,2)}}}RUN.intr=1}}put('C',2);put('E',rnd(2,3));if(Math.random()<.6||isBoss)put('L',1);
 RUN.grid=g;RUN.mon=mon;RUN.x=sx;RUN.y=sy;RUN.seen=new Set();RUN.lantern=false;reveal();
 if(f>S.maxF&&!RUN.abyss&&!RUN.portal)S.maxF=f;RUN.deepest=Math.max(RUN.deepest||0,f);if(RUN.gen>0){bump('deep');taintFloor()}
 $('loc').textContent=RUN.portal?`白鐵礦城北境分站・第 ${f-39} 層`:RUN.abyss?`異世界的深淵・第 ${RUN.depth} 層`:f>=15?`地底分站・第 ${f} 層`:f>=10?`逆址郵廊・第 ${f} 層・門牌 ${15-f}`:`無字地窖・第 ${f} 層・${T.name.split('・')[1]}`;
 if(RUN.bless==='dream_heal'&&RUN.gen>0)healAll(.15);famFloor();if(f>=10&&!RUN.abyss&&!RUN.portal){setTimeout(()=>{if(RUN&&!BAT)ch2Scene(f)||ch3Scene(f)},300)}if(RUN.portal&&f>40)setTimeout(()=>{if(RUN&&!BAT)ptlScene(f)},300);if(RUN.party.some(q=>q.hp>0&&q.fx&&q.fx.pathMark))showStairs();RUN.gen++}
function reveal(){const r=RUN.torch>0?1:0;const fog=S.weather==='fog'&&!RUN.mem;for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){if(fog&&dx&&dy)continue;RUN.seen.add((RUN.y+dy)+','+(RUN.x+dx))}}
function glyph(ch,x,y){if(ch==='M'){const m=RUN.mon[x+','+y];return (m.chief?'♛':m.elite?'★':'')+FOES[m.k].g}return {C:'箱',E:'？',L:'燈',B:'王',U:'↑',D:'↓'}[ch]||''}
