  if(!RUN.seen.has(k))cls+=' fog';else if(ch==='#')cls+=' wall';else{cls+=' floor';txt=glyph(ch,x,y);cls+=' '+({M:RUN.mon[x+','+y]&&RUN.mon[x+','+y].chief?'m el ch':RUN.mon[x+','+y]&&(RUN.mon[x+','+y].elite||RUN.mon[x+','+y].hidden)?'m el':'m',B:'b',C:'c',E:'e',L:'f',D:'d'}[ch]||'');if(pathSet.has(k))cls+=' path';if(y===RUN.y&&x===RUN.x){cls+=' me';txt='⚑'}}
