function findPath(tx,ty){const g=RUN.grid,H=g.length,W=g[0].length,key=(x,y)=>x+','+y;const q=[[RUN.x,RUN.y]],prev={[key(RUN.x,RUN.y)]:null};
 while(q.length){const [x,y]=q.shift();if(x===tx&&y===ty)break;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=key(nx,ny);if(nx<0||ny<0||nx>=W||ny>=H||g[ny][nx]==='#'||prev[k]!==undefined)continue;
  if(!RUN.seen.has(ny+','+nx))continue;const ch=g[ny][nx];if('MBCELUD'.includes(ch)&&!(nx===tx&&ny===ty))continue;prev[k]=[x,y];q.push([nx,ny])}}
 if(prev[key(tx,ty)]===undefined)return null;const path=[];let cur=[tx,ty];while(cur&&!(cur[0]===RUN.x&&cur[1]===RUN.y)){path.unshift(cur);cur=prev[key(cur[0],cur[1])]}return path}
