let VNS=null;
function vnSegs(s){const seg=[];const clean=t=>String(t).replace(/<br\s*\/?>/g,'\n').replace(/<[^>]+>/g,'');
 if(s.a)seg.push(['vact',clean(s.a)]);if(s.n)seg.push(['vnar',clean(s.n)]);if(s.s)seg.push(['vsay',clean(s.s)]);if(s.r)seg.push(['vres',clean(s.r)]);return seg}
function vn(o){closeModal();const el=$('vn');VNS={o,i:0,tm:null};
 let bg='';if(o.bg)bg=`background-image:url('${A(o.bg)}')`;else{const b=document.querySelector('#stage .bg');if(b)bg=b.getAttribute('style')||''}
 const imgs=o.imgs||[];
 el.innerHTML=`<div class="vbg" style="${bg}"></div><div class="vchars ${imgs.length>1?'duo':''}">${imgs.map((m,j)=>`<img id="vi${j}" class="${m.c||''}" src="${A(m.k)}" alt="">`).join('')}</div><div class="vfog"></div>${o.title?`<div class="vtitle">${o.title}</div>`:''}<div class="vmark" id="vmark"></div><div class="vlow"><div class="vopts" id="vopts"></div><div class="vbox" id="vbox"><span class="vname" id="vname"></span><div id="vtext"></div><span class="vnext" id="vnext">▼</span></div></div>`;
 el.classList.remove('hide');$('vbox').onclick=vnTap;vnShow()}
function vnClose(){const el=$('vn');if(VNS&&VNS.tm)clearInterval(VNS.tm);VNS=null;el.classList.add('hide');el.innerHTML=''}
function vnShow(){const V=VNS,o=V.o,s=o.steps[V.i]||{};
 const nm=$('vname');nm.textContent=s.w||'';nm.style.display=s.w?'':'none';
 if(s.k){let im=$('vi0');if(!im){document.querySelector('#vn .vchars').innerHTML=`<img id="vi0" src="" alt="">`;im=$('vi0')}if(im.dataset.k!==s.k){im.dataset.k=s.k;im.src=A(s.k);im.classList.remove('vin');void im.offsetWidth;im.classList.add('vin')}}
 if(s.i!=null)(o.imgs||[]).forEach((m,j)=>{const im=$('vi'+j);if(im)im.classList.toggle('dim',j!==s.i)});
 $('vopts').innerHTML='';$('vnext').style.display='none';const tx=$('vtext');
 if(s.h){tx.innerHTML=s.h;return vnEnd()}
 const segs=vnSegs(s);tx.innerHTML=segs.map((g,j)=>`<div class="${g[0]}" id="vs${j}"></div>`).join('');
 let gi=0,ci=0;if(V.tm)clearInterval(V.tm);
 V.full=()=>{segs.forEach((g,j)=>{const e=$('vs'+j);if(e)e.textContent=g[1]});clearInterval(V.tm);V.tm=null;vnEnd()};
 V.tm=setInterval(()=>{if(!VNS){return}if(gi>=segs.length)return V.full();const e=$('vs'+gi);if(!e)return V.full();ci+=2;e.textContent=segs[gi][1].slice(0,ci);if(ci>=segs[gi][1].length){gi++;ci=0}},28)}
function vnEnd(){const V=VNS;if(!V)return;const o=V.o,last=V.i>=o.steps.length-1;
 if(!last){$('vnext').style.display='';return}
 if(o.mark){const m=$('vmark');m.className='vmark '+o.mark;m.innerHTML=o.mark==='fox'?FOXSVG:''}
 const opts=o.opts&&o.opts.length?o.opts:[{t:'繼續'}];
 const groups=[];opts.forEach((op,j)=>{const g=op.g||('_'+j);let gr=groups.find(x=>x.g===g);if(!gr){gr={g,b:[]};groups.push(gr)}gr.b.push([op,j])});
 $('vopts').innerHTML=groups.map(gr=>`<div class="vrow">${gr.b.map(([op,j])=>`<button class="btn ${op.p?'primary':''}" data-j="${j}">${op.t}</button>`).join('')}</div>`).join('');
 document.querySelectorAll('#vopts button').forEach(b=>b.onclick=()=>{sfx('click');const op=opts[+b.dataset.j];const done=o.done;
  if(!op.f){vnClose();done&&done();return}
  vnClose();const r=op.f();if(r&&r.steps)vn({title:o.title,bg:o.bg,imgs:o.imgs,done:o.done,...r})})}
function vnTap(){const V=VNS;if(!V)return;if(V.tm){V.full();return}if(V.i<V.o.steps.length-1){V.i++;vnShow()}}
