function logDeath(){const L=LG();L.d.push([RUN?RUN.floor:0,RUN&&RUN.lastFoe?FOES[RUN.lastFoe].name:'?',partyLv(),RUN?RUN.party.map(p=>CLS[p.cls].name).join('/'):'']);if(L.d.length>40)L.d.shift()}
function logBoss(kind,turns){const L=LG();L.b.push([FOES[kind].name,turns,partyLv(),RUN.party.filter(p=>p.hp<=0).length,!!RUN.mem]);if(L.b.length>40)L.b.shift()}
