const YTAUNT={ys3:['「鱗片很漂亮吧？摸摸看呀。」'],yfw:['「先從白色的開始。」'],yfr:['「再紅一點就好。」'],yfb:['「嗚——……這次是真的狐狸喔。」'],ygl:['「看得清楚嗎？看不清楚也沒關係。」'],yat:['「答一題再走。答錯就留下來發芽。」'],ytr:['「多一倍，你才不會無聊。」'],ytb:['「別怕，水只到脖子。」'],ysc1:['「別碰我的尾巴。」'],ysc2:['「說了別碰的。」'],ywi:['「噓——聽到了嗎？有人在哭。」'],ygh:['「我在你後面。」'],yve:['「你是來接我的嗎？」'],yl1:['「迷路了？我也會帶路。」'],yan:['「看，好亮的燈喔。走過來呀。」','「她提燈是為了照路，我提燈是為了吃人。開玩笑的。」'],yz1:['「再靠近一點，看清楚。」','「這才是我喜歡的樣子。」'],yz2:['「每一隻眼睛，都在看你。」','「別眨眼。」'],yz3:['「怕嗎？……怕就對了。」','「我很強的。你們也很強。」','「最後一次，全力陪我。」'],yb1:['「往左走？往右走？尾巴說了算。」','「站好位置喔，等一下就不是你的了。」'],yb2:['「別踩到裙襬，很難洗的。」','「等待原本就不是兩個人的事。」','「你是來接我的嗎？……不是？那就陪我玩。」'],yf1:['「猜一個呀。」','「選得好不好，要打開才知道。」','「第二個選擇總顯得比較聰明。」'],yl1:['「迷路了？我也會帶路。」','「有些黑暗，只是在等你看清顏色。」','「不是她喔。」'],yf2:['「不借你的名字，只借一句話。」','「空白也很好。」','「有些話不用寫下來，也不會消失。」'],yh1:['「答一題再走。」','「有門框，不代表後面一定有路。」','「沒有誰規定你一定得進門。」'],yf3:['「嗚——怪物來啦！」','「至少緊張一下嘛！」','「你問的是腕足，還是藏在後面的我？」'],yl2:['「別急著替所有陌生人取同一個名字。」','「我是坐在燈旁的人。這句可沒有騙你。」','「玩夠了嗎？我還沒呢。」']};
const YINTRO={ysc:[{n:'房間裡全是沙。沙裡有東西在動，尾巴的影子像一把鉤子。'},{w:'蠍尾的客人',k:'y_scorp',s:'「客人來了。……請不要碰我的尾巴，它很怕生。」'}],ywi:[{n:'房間很暗，只有幾團藍色的火飄在空中。有人在很遠的地方哭。'},{w:'提著鬼火的人',k:'y_wisp',s:'「噓——你也聽到了嗎？」'}],yln:[{n:'房間像一片深海。黑暗裡亮著一盞冷藍色的燈，燈下好像有人。'},{w:'藍燈',k:'y_blue',s:'「迷路了嗎？跟著燈走就好。」'}],yb:[{n:'門後是一條鋪著舊地毯的長廊。地毯上，一截蛇尾盤成戒指般的圓圈。'},{w:'蛇尾旅人',k:'y_snake',s:'「你信木牌、信尾巴，還是信自己的眼睛？」'}],yf:[{n:'石階上並排放著兩只黑木盒。九條尾巴在盒後慢悠悠地晃。'},{w:'兩只黑盒子的見證人',k:'y_fox9',s:'「來，猜一個。猜錯了也沒關係，我會陪你玩到猜對為止。」'}],ym:[{n:'房間裡飄滿了書頁，像一群薄翅。'},{w:'收字的夜蛾',k:'y_moth',s:'「今天想留下什麼話？不說也沒關係，我自己來收。」'}],yh:[{n:'一扇只有門框的窄門前，長角的女人坐在門檻上，用指甲敲著空鉸鏈。'},{w:'半扇門的門房',k:'y_horn',s:'「答一題再走。答錯了……就留下來陪我。」'}],yt:[{n:'燈全熄了。黑暗裡，有很多東西在動。'},{w:'？？？',k:'y_tent',s:'「嗚——怪物來啦！……喂，這次可是真的喔。」'}],yx:[{n:'所有的燈一起亮了，暖黃的、冷藍的，一盞接一盞。'},{w:'燈旁的陌生人',k:'y_base',s:'「都玩過一輪了？那最後，陪我玩全部吧。」'}]};
const YLINE={ys3:'白紗落下，蛇尾長出了青綠色的鱗。',yfw:'盒子散開，一條白色的尾巴從霧裡伸出來。',yfr:'白尾一條一條被染紅了。',yfb:'九條尾巴縮成一團，她四肢著地，變成了狐。',ygl:'夜蛾散開，變成一片會呼吸的霧。',yat:'門框上長出了枝椏，角也跟著分了岔。',ytr:'腕足變成暗紅色，數量多了一倍。',ytb:'燈全熄了。觸手從水底下伸上來。',ysc2:'她的尾針翹了起來。',ygh:'鬼火熄了，只剩一個灰色的影子。',yve:'影子披上了白紗。「你是來接我的嗎？」',yan:'藍燈沉進水裡。深處，有另一盞燈亮了起來。',yz1:'她把狐狸面具往上推了一點。九條尾巴同時睜開了眼睛。',yz2:'尾巴上的眼睛一起轉過來，看著你們每一個人。',yz3:'所有的燈都熄了，只剩她頭頂那一圈黑色的光。「……玩到這裡，可以給你們看了。」',yl1:'九條尾巴一起燒了起來，火變成了冷藍色。',yb2:'「啊呀，被你們逼出原形了。」白紗從頭頂落下來。',yl2:'藍色的燈熄了。燈旁坐著另一個人，狐狸尾巴慢慢地晃。',yf2:'盒子散成一群紙蛾。「換一個玩法吧。」',yf3:'紙蛾聚成一團，長出了好多腕足。「這次真的要嚇你了！」'};
