Object.assign(YTAUNT,{"yc1": ["「別怕，繭裡面很溫暖。」", "「孵出來的會是誰呢？」"], "yc2": ["「看鏡子。裡面那個比較乖。」"], "yc3": ["「我縫起來了，這樣就會一直笑了。」"], "yc4": ["「借過，送葬的隊伍不能停。」"], "yc5": ["「這裡每一塊碑，都是我的客人。」"], "yc6": ["「水不深，只是沒有底。」"], "yc7": ["「名字放進抽屜，就不會弄丟了。」"], "yc8": ["「倒過來看，世界比較誠實。」"], "yc9": ["「這條鐵軌只往前，不回頭。」"], "yc10": ["「鏡子裡有九個我。找得到真的那個嗎？」"], "yc11": ["「時間到了。……開玩笑的，是我到了。」"], "yc12": ["「別動。網會醒。」"]});Object.assign(YLINE,{"yc1": "月光暗下來，她懷裡的繭一顆一顆裂開。", "yc2": "鏡子轉過來，鳳冠上的金羽一根根豎起。", "yc3": "她把縫線拉緊，臉上的笑變得更大了。", "yc4": "紙錢從天上落下來，紅衣的隊伍從霧裡走出來。", "yc5": "黑羽從四面八方飛回她身上，墓碑一起轉向你們。", "yc6": "地板變成了水，長髮從水底慢慢浮上來。", "yc7": "整面牆的抽屜同時拉開，每一格都裝著一個名字。", "yc8": "房間倒過來了。她垂掛在天花板上，看著你們。", "yc9": "鐵軌從牆裡伸出來，隧道兩邊的眼睛一起睜開。", "yc10": "鏡子一面接一面亮起來，每一面裡都有一個她。", "yc11": "所有的鐘一起倒轉，紅色的翅膀從鐘面後面張開。", "yc12": "月亮升起來。網上的每一根絲都在發光。"});YINTRO.ych=[{"n": "遊樂坊最裡面多了一扇沒有把手的門。門縫裡一下是月光，一下是紙錢，一下是水。"}, {"w": "燈旁的陌生人", "k": "y_ex_laugh", "s": "「這間是混沌。我自己也不知道下一個會是哪個我。……猜猜看？」"}];YPH.ych=YC_ALL.slice(0,5);
