function initCurios(o){
 if(!o.curioStock)o.curioStock=Object.fromEntries(Object.keys(CURIO).filter(k=>(o.curio||{})[k]).map(k=>[k,1]));
 if(!Array.isArray(o.cabinet))o.cabinet=[];
 if(!o.curioGifts)o.curioGifts={};if(!o.curioSets)o.curioSets={};return o;
}
const sanitize153=sanitize;
sanitize=function(o){const f=sanitize153(o);if(!f)return f;
 if(o.curioStock&&typeof o.curioStock==='object')f.curioStock=Object.fromEntries(Object.keys(CURIO).map(k=>[k,Math.min(999,n0(o.curioStock[k],0))]));
 f.cabinet=Array.isArray(o.cabinet)?[...new Set(o.cabinet.filter(k=>CURIO[k]&&(f.curio||{})[k]))].slice(0,3):[];
 f.curioSets=Object.fromEntries(Object.keys(CURIO_SETS).filter(k=>o.curioSets&&o.curioSets[k]).map(k=>[k,1]));
 f.curioGifts=Object.fromEntries(Object.keys(NPC).filter(k=>o.curioGifts&&Number.isInteger(o.curioGifts[k])).map(k=>[k,o.curioGifts[k]]));
 return initCurios(f);
};
curioGet=function(id){if(!CURIO[id])return '';initCurios(S);const first=!(S.curio||{})[id];S.curio=S.curio||{};S.curio[id]=1;S.curioStock[id]=Math.min(999,(S.curioStock[id]||0)+1);return '（'+(first?'收集冊新增：':'再次拾獲：')+CURIO[id][0]+' ×1）'};
const mkP153=mkP;
mkP=function(...args){const p=mkP153(...args);initCurios(S);for(const k of S.cabinet){const b=CURIO_BONUS[k];if(!b)continue;const [,stat,value]=b;if(stat==='hp')p.maxhp=Math.round(p.maxhp*(1+value));else if(stat==='def')p.def=Math.round(p.def*(1+value));else p[stat]=(p[stat]||0)+value;}p.hp=p.maxhp;p.mhp0=p.maxhp;return p;};
function curiosMenu(tab='stock'){
 initCurios(S);const owned=Object.keys(CURIO).filter(k=>(S.curio||{})[k]);
 const tabs=`<div class="tabs">${[['stock','收藏背包'],['shelf','陳列架'],['sets','成套交換']].map(([k,n])=>`<button class="tab ${tab===k?'on':''}" onclick="curiosMenu('${k}')">${n}</button>`).join('')}</div>`;
 let body='';
 if(tab==='stock')body='<p class="note">拾獲的小東西可以送給村民、擺上陳列架，或湊成一組交換。使用副本後，收集冊的發現紀錄仍會保留。</p>'+(owned.length?owned.map(k=>`<div class="hero">${icn(CURIO_ICONS[k],44)}<div class="info"><b>${esc(CURIO[k][0])}</b><br>背包 ×${S.curioStock[k]||0}${S.cabinet.includes(k)?'・陳列中':''}<br><span class="note">${CURIO_BONUS[k][0]}</span></div><button class="btn small" ${(S.curioStock[k]||0)>0?'':'disabled'} onclick="curioGiftMenu('${k}')">贈送</button><button class="btn small" ${(S.curioStock[k]||0)>0&&!S.cabinet.includes(k)&&S.cabinet.length<S.shelf156?'':'disabled'} onclick="curioPlace('${k}')">陳列</button></div>`).join(''):'<p>還沒有拾獲收藏品。先去地窖探索吧。</p>');
 if(tab==='shelf')body=`<p class="note">最多陳列 3 件不同物品，小加成在出發時套用。取下會歸還背包，不會消失。</p>`+Array.from({length:S.shelf156||3},(_,i)=>{const k=S.cabinet[i];return k?`<div class="hero">${icn(CURIO_ICONS[k],44)}<div class="info"><b>${esc(CURIO[k][0])}</b><br>${CURIO_BONUS[k][0]}</div><button class="btn small" onclick="curioRemove('${k}')">取下</button></div>`:'<div class="hero"><p class="note">空的陳列位</p></div>'}).join('');
 if(tab==='sets')body='<p class="note">每組獎勵只能交換一次，會消耗列出的背包副本；陳列中的物品請先取下。</p>'+Object.entries(CURIO_SETS).map(([k,v])=>`<div class="q"><b>${v.n}</b><p>${v.keys.map(id=>esc(CURIO[id][0])+' ×1（持有 '+(S.curioStock[id]||0)+'）').join('<br>')}</p><p class="note">獎勵：積分 ${v.pts}、${needTxt(v.mats)}</p><button class="btn small" ${!S.curioSets[k]&&v.keys.every(id=>(S.curioStock[id]||0)>0)?'':'disabled'} onclick="curioExchange('${k}')">${S.curioSets[k]?'已領取':'交換'}</button></div>`).join('');
 modal(`<h2>收藏品工房</h2>${tabs}${body}<div class="row"><button class="btn" onclick="curiosMenu()">收藏背包</button><button class="btn primary" onclick="closeModal();bag()">回倉庫</button></div>`);
}
function curioPlace(k){initCurios(S);if(RUN||!CURIO[k]||!(S.curioStock[k]>0)||S.cabinet.length>=3||S.cabinet.includes(k))return;S.curioStock[k]--;S.cabinet.push(k);save();curiosMenu('shelf')}
function curioRemove(k){initCurios(S);if(RUN||!S.cabinet.includes(k))return;S.cabinet=S.cabinet.filter(x=>x!==k);S.curioStock[k]=(S.curioStock[k]||0)+1;save();curiosMenu('shelf')}
function curioGiftMenu(k){if(!CURIO[k])return;const people=['bai','mo','yan','chen','sui','sang','su','zh','ye'].filter(n=>NPC[n]&&(S.met||{})[n]);modal(`<h2>贈送${esc(CURIO[k][0])}</h2><p class="note">每位村民在本次歸來期間只收一份收藏品。贈送消耗 1 件，好感 +4。</p>${people.map(n=>`<button class="btn" ${(S.curioStock[k]||0)>0&&S.curioGifts[n]!==S.returns?'':'disabled'} onclick="curioGift('${k}','${n}')">${esc(NPC[n].name)}${S.curioGifts[n]===S.returns?'（已送過）':''}</button>`).join('')||'<p>先到村裡認識居民，再送禮吧。</p>'}<div class="row"><button class="btn" onclick="curiosMenu()">返回</button></div>`)}
function curioGift(k,n){initCurios(S);if(RUN||!CURIO[k]||!NPC[n]||!(S.met||{})[n]||!(S.curioStock[k]>0)||S.curioGifts[n]===S.returns)return;S.curioStock[k]--;S.curioGifts[n]=S.returns;addAff(n,4);save();toast(NPC[n].name+' 收下了禮物，好感 +4。');curiosMenu()}
function curioExchange(k){initCurios(S);const r=CURIO_SETS[k];if(RUN||!r||S.curioSets[k]||!r.keys.every(id=>(S.curioStock[id]||0)>0))return;r.keys.forEach(id=>S.curioStock[id]--);S.curioSets[k]=1;S.pts+=r.pts;for(const [m,v] of Object.entries(r.mats))S.mats[m]=(S.mats[m]||0)+v;save();res();toast('已換取「'+r.n+'」獎勵。');curiosMenu('sets')}

