const STATUS_HELP154={taunt:'優先吸引敵方單體攻擊；部分高難度心情可無視嘲諷。',hold:'堅守期間受到的直接傷害減半。',ward:'受到的直接傷害降低 30%。',regen:'每回合恢復狀態上記錄的生命量；會受減療、禁療影響。',stun:'失去行動機會。可由淨化解除，控制抗性可降低命中機率。',slow:'行動排序速度 -3。',mark:'受到的直接傷害增加 30%。',burn:'每回合受到燃燒傷害；角色基礎值依施加者攻擊的 50% 計算，再受天賦調整。',poison:'每回合受到毒傷；角色基礎值依施加者攻擊的 45% 計算，再受天賦調整。部分敵人中毒時自療降低。',weak:'削弱攻擊；敵方攻擊降為原本的 70%。',counter:'受到攻擊時可觸發反擊，實際倍率依來源技能與天賦。',spike:'架槍等待敵人攻擊，可觸發槍系迎擊。',bleed:'每回合按基礎流血量 × 層數扣血；可被特定長槍技能引爆。',freeze:'凍結後失去行動機會；可由淨化解除。',prey:'指定狩獵目標，讓獵手的優先選敵與相關天賦生效。',link:'將敵人連結，使連結技能的傷害傳遞與天賦生效。',might:'攻擊強化；我方攻擊計算增加 20%。',evade:'提升閃避，數值依來源技能。',riposte:'影步狀態，配合影步技能進行閃避反擊。',proxy:'替身線保護，傷害轉移效果依技能與天賦。',cover:'正受到隊友保護，部分傷害由保護者承接。',silence:'無法正常施放主動招式；可改用普通攻擊。',fury:'狂怒層數會提高敵方攻擊；久戰狂怒每層另壓低我方治療，最低仍保留 30%。',hide:'隱身配合刺客技能避開索敵，特定技能可在下一擊保證暴擊。',lit:'照明標記，配合提燈技能與對照明目標增傷的天賦。',pure:'淨身保護，阻擋部分負面狀態，持續時間依技能。',umb:'頂盾姿態，配合盾衛技能阻擋或保護隊友。',wall:'聖壁保護，具體減傷與反應依施加技能。',blind:'致盲使攻擊更容易落空；命中可部分抵消。',terror:'恐懼控制，影響行動；探索隊伍的恐懼層數另會降低攻擊。',brk:'直接傷害計算時，目標防禦按 60% 計算。',hcut:'受到的治療降低 50%。',nheal:'無法受到治療；優先淨化後再恢復。',curse:'受到的直接治療降低 50%，可與減療疊加。',vuln:'受到的直接傷害增加 20%。',erode:'可疊層的持續傷害；每層另使傷害計算使用的防禦降低 6%。',erase:'褪名使技能施放可能失敗；敵方回合超過一回合後，招式有 60% 機率無法正常施放。',doom:'累積受傷的延爆詛咒；倒數結束時引爆基礎傷害與累積值。',seal:'封印敵方自我強化與低血量狂暴；部分技能另有特殊封印效果。',charm:'魅惑可能使行動轉向自己的同伴，控制抗性可降低附加機率。',echo:'迴響狀態；效果依施加招式，可重複或呼應先前行動。',breath:'屏息時抵銷下一次直接命中，觸發後解除。',shell:'縮殼時抵擋直接命中；持續與限制依來源技能。',vow:'誓約保護；與騎士的救援及保命技能連動。'};
const ATTR_HELP154={str:['力量','提高力量系職業攻擊；所有角色攻擊也得到少量力量加成，並提高暴擊傷害。'],spd:['速度','決定回合內行動順序，排序帶有少量隨機浮動。'],dex:['敏捷','提高暴擊、閃避、防暴擊、命中與幸運。'],int:['智慧','提高技能威力、魔法抗性與異常抗性；智慧系職業的主攻屬性。'],vit:['體質','提高最大生命、防禦、物理抗性與控制抗性。'],hp:['生命','歸零後倒下；一般地窖戰可能造成重傷或死亡，訓練與遊樂坊依房間規則處理。'],atk:['攻擊','普通攻擊與多數技能傷害的基礎；倍率、防禦、抗性、天賦會再調整。'],def:['防禦','降低受到的直接攻擊傷害；破甲、侵蝕及穿透會削弱它。'],pow:['技能威力','乘入適用技能的傷害計算，智慧、法器與裝備都可增加。'],crit:['暴擊','造成暴擊的機率；敵方防暴擊會降低機率。'],cdm:['暴擊傷害','暴擊時使用的傷害倍率，與暴擊機率分開。'],crr:['防暴擊','降低敵人對自己造成暴擊的機率。'],luk:['幸運','參與探索與寶箱等機率判定，不等同於掉寶率。'],drop:['掉寶','提高適用的裝備掉落判定，不保證傳說或史詩。'],pres:['物理抗性','在防禦計算後降低物理直接傷害。'],mres:['魔法抗性','在防禦計算後降低魔法直接傷害。'],ls:['吸血','按實際造成的傷害回復自身生命，仍受治療相關限制。'],acc:['命中','降低攻擊因閃避、致盲等原因落空的機會。'],thn:['反傷','受到有效傷害後，按比例反射傷害給攻擊者。'],cres:['控制抗性','降低暈眩、凍結、魅惑等控制狀態附加機率。'],ares:['異常抗性','降低中毒、燃燒等異常狀態附加機率。'],blk:['格擋','觸發盾牌格擋時直接傷害減半；與防禦分開計算。'],shield:['護盾','先替生命承受適用的直接傷害；不是生命上限。'],res:['敵方抗性','怪物各自具有物理與魔法抗性，不能用外觀判定。'],cd:['冷卻與回合','冷卻影響能否再次施放；狀態持續回合依觸發與倒數時機消耗。']};
function encNav154(tab){return `<div class="tabs enc-tabs">${[['attrs','屬性'],['status','狀態'],['hero','角色技能'],['monster','怪物'],['boss','首領'],['gear','裝備故事']].map(([k,n])=>`<button class="tab ${k===tab?'on':''}" onclick="encyclopedia154('${k}')">${n}</button>`).join('')}</div>`;}
function encCard154(n,d,extra=''){return `<details class="q enc-entry" data-search="${esc((n+' '+d).toLowerCase())}"><summary>${esc(n)}</summary><p>${d}</p>${extra}</details>`;}
function enemyEntry154(k){const f=FOES[k],res=FRES[k]||[0,0],skills=FSK[k]||[];return encCard154(f.name,`基礎生命 ${f.hp}・攻擊 ${f.atk}・防禦 ${f.def||0}・速度 ${f.spd||0}<br>物理抗性 ${Math.round(res[0]*100)}%・魔法抗性 ${Math.round(res[1]*100)}%<br><span class="note">實戰數值另受等級、精英／首領、主宰、心情與房間修正。</span>`,skills.map(s=>`<div class="q">${monsterSkillExplain(s)}${s.cd?`<p class="note">冷卻 ${s.cd} 回合</p>`:''}</div>`).join('')||'<p>使用普通攻擊。</p>');}
function encyclopedia154(tab='attrs'){
 let body='';
 if(tab==='attrs')body=Object.values(ATTR_HELP154).map(([n,d])=>encCard154(n,esc(d))).join('');
 if(tab==='status')body=Object.entries(STI).map(([k,v])=>encCard154(v[1],esc(STATUS_HELP154[k]))).join('');
 if(tab==='hero')body=CANDS.map(c=>{const keys=new Set([...baseOf(c.key).map(x=>x[0]),...branches200(c.key).flatMap(b=>b.s),...(CHR[c.key]?.br2||[]).map(b=>b.s),'aw_'+c.key]);return encCard154(c.name,CLS[c.cls].name,[...keys].filter(k=>SK[k]).map(k=>{const s=SK[k];return `<div class="q"><b>${esc(s.n)}</b><p>${esc(s.d||'依技能條件觸發。')}</p><span class="note">${s.cd?'冷卻 '+s.cd+' 回合':''}${s.once?'・每場限用':''}${s.st?'・附加 '+esc(STI[s.st[0]]?.[1]||s.st[0]):''}</span></div>`;}).join(''));}).join('');
 if(tab==='monster')body=Object.keys(FOES).filter(k=>!FOES[k].boss&&!FOES[k].yy&&!NPC[k]).map(enemyEntry154).join('');
 if(tab==='boss')body='<p class="note">包含領主、主宰異變及她各型態。以下是機制資料，實戰會套用房間與心情修正。</p>'+Object.keys(FOES).filter(k=>FOES[k].boss||FOES[k].yy).map(enemyEntry154).join('')+encCard154('精英、首領與主宰','精英提高基礎能力；首領有額外行動與招式；主宰將原招式傷害提高至 1.35 倍，並有異變階段。',`<div class="q">${monsterSkillExplain({n:'首領的號令',t:'aoe',m:.85,st:['terror',1,.45]})}</div><div class="q">${monsterSkillExplain({n:'壓上來',t:'hit',m:2.2,st:['brk',2]})}</div><div class="q">${monsterSkillExplain({n:'主宰的低語',t:'aoe',m:1,st:['hcut',2,.7]})}</div>`)+encCard154('心情追加招式與狂暴','依目前心情與敵方狂暴條件追加，並非每場全部出現。',[...DSK,...Object.values(RAGE),...RAGE_GEN].filter(s=>s&&s.n).map(s=>`<div class="q">${monsterSkillExplain(s)}</div>`).join(''));
 if(tab==='gear')body='<p class="note">特色可從地窖、委託與事件取得；新增特色加入地窖特色掉落池。傳說加入傳說掉落與碎片交換池；新增史詩加入回憶房主宰獎勵池。故事為本版新增的世界片段。</p>'+Object.entries(UQ).map(([k,u])=>encCard154(u.n,esc(u.d),`<p class="tag">${u.ep?'史詩・來歷':u.leg?'傳說・殘片':'特色・殘片'}</p><p class="lore">${esc(u.lore)}</p>`)).join('')+Object.entries(SETS).map(([k,x])=>encCard154(x.n+'套裝',esc(x.b2)+(x.b4?'<br>4 件：'+esc(x.b4):'')+(x.b6?'<br>6 件：'+esc(x.b6):''),Object.keys(x.parts||{s:1,g:1}).map(s=>{const it={s,set:k,atk:0,def:0,at:{},x:{}};return `<p class="lore">${x.parts?esc(x.parts[s])+'：':''}${gearDesc(it).split('套裝殘片：').pop().split('過往殘片：').pop().replace(/<\/span>$/,'')}</p>`;}).join(''))).join('');
 modal(`<h2>渡鴉百科</h2><p class="note">角色、怪物與首領的技能與屬性說明。可查閱未遭遇型態；原圖鑑的擊倒紀錄與收集條件保持獨立。</p>${encNav154(tab)}<label class="enc-search">搜尋<input id="encSearch154" type="search" placeholder="名稱或效果" oninput="filterEnc154(this.value)"></label><div id="encEntries154">${body}</div><div class="row"><button class="btn primary" onclick="codexMenu('mon')">回圖鑑</button><button class="btn" onclick="closeModal()">離開</button></div>`);
}
function filterEnc154(q){q=q.trim().toLowerCase();document.querySelectorAll('#encEntries154>.enc-entry').forEach(e=>{e.hidden=q&&!e.textContent.toLowerCase().includes(q);});}
