bossCraftMenu=function(){init190(S);modal(`<h2>首領套裝・定向打造</h2><p>同一首領素材可打造整套的不同部位。先取得對應素材或裝備後解鎖配方；裝備等級跟隨領取時隊伍等級。套裝效果保留各自打法。</p>${Object.entries(BMSET).map(([mat,id])=>{const set=SETS[id],parts=ownedParts(id),cost=bossCraftCost190(mat),open=bossUnlocked190(mat);return `<details class="q" data-boss190="${mat}"><summary>${set.n}${open?'':'・未解鎖'}</summary><p>部位進度 ${parts.size}/${Object.keys(set.parts).length}</p><p>素材：${BMN[mat]} ${S.bmat?.[mat]||0}；來源：${Object.keys(BOSSMAT).filter(k=>BOSSMAT[k][0]===mat).map(k=>FOES[k]?.name||k).join('、')}</p><p>2件：${set.b2}<br>4件：${set.b4}${set.b6?'<br>6件：'+set.b6:''}</p><p>每件需專屬素材1、積分${cost.pts}、${materialText156({scrap:cost.scrap,thread:cost.thread,crystal:cost.crystal})}</p>${Object.entries(set.parts).map(([sl,n])=>`<button class="btn small" ${!idle180()||!open||!(S.bmat[mat]>0)||S.pts<cost.pts||!canMaterials156({scrap:cost.scrap,thread:cost.thread,crystal:cost.crystal})?'disabled':''} onclick="bossCraft('${mat}','${sl}')">${n}${parts.has(sl)?'（已有）':'（缺件）'}</button>`).join('')}<button class="btn small" ${!open?'disabled':''} onclick="bossRecraftMenu190('${mat}')">同套部位轉製</button></details>`;}).join('')}<button class="btn" onclick="workshop()">返回工匠房</button>`);};
bossCraft=function(mat,sl){if(!idle180()||!BMSET[mat]||!SETS[BMSET[mat]].parts[sl]||!bossUnlocked190(mat))return;const c=bossCraftCost190(mat),m={scrap:c.scrap,thread:c.thread,crystal:c.crystal};if(!(S.bmat[mat]>0)||S.pts<c.pts||!canMaterials156(m))return;const old=LOOT190;LOOT190={focus:itemFocus190(),floor:.75};let it;try{it=mkSet(BMSET[mat],sl);}finally{LOOT190=old;}S.bmat[mat]--;S.pts-=c.pts;payMaterials156(m);relevel170(it,playerLevel156(),true);S.bag.push(it);save();res();bossCraftMenu();};
