function bossRecraft190(u,mat,sl){if(!idle180())return;const it=S.bag.find(it=>it.u===u),id=BMSET[mat];if(!it||it.locked||it.uq||it.set!==id||it.s===sl||!SETS[id]?.parts[sl]||!(S.bmat[mat]>0)||!canMaterials156({thread:5,crystal:2}))return;const next=mkSet(id,sl);while(next.t<it.t){const r=TUPR[next.t]||1.12;next.atk=Math.round(next.atk*r);next.def=Math.round(next.def*r);for(const k in next.at)next.at[k]=Math.round(next.at[k]*r);next.t++;}relevel170(next,Math.max(it.ilv,playerLevel156()),true);next.x={...(it.x||{})};next.u=it.u;if(it.tem)next.tem=it.tem;if(it.affinity190)next.affinity190=it.affinity190;if(it.e){for(const k of ['e5k','e5v','e8k','e8v','e10k','e10v'])if(it[k]!=null)next[k]=it[k];enhApply(next,it.e);}S.bmat[mat]--;payMaterials156({thread:5,crystal:2});S.bag[S.bag.indexOf(it)]=next;save();bossRecraftMenu190(mat);}
const MP190=mkP;mkP=function(h,...a){const p=MP190(h,...a),n=setCount(h.eq).sort190||0;if(n>=2)p.fx.cdRate=(p.fx.cdRate||0)+.06;if(n>=4)p.fx.statusAcc=(p.fx.statusAcc||0)+.06;if(n>=6)p.fx.firstNoCd=1;return p;};
