function backTitle(){if(BAT)return modal(`<h2>回到首頁</h2><p>戰鬥中不能離開。打完這場再說吧。</p><div class="row"><button class="btn primary" onclick="closeModal()">好</button></div>`);
 if(RUN)return modal(`<h2>要放棄這次下潛嗎？</h2><p>回到首頁會直接回到地面，<b>這次帶著的戰利品會全部留在地窖裡</b>。</p><div class="row"><button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="backTitleGo(1)">放棄並回首頁</button></div>`);
 backTitleGo(0)}
function backTitleGo(ab){if(ab&&RUN){const L=RUN.loot;L.pts=0;for(const m in MAT)L[m]=0;L.gear=[];endRun()}save();closeModal();hadSave=true;title()}
function zoomImg(src,flt){const d=document.createElement('div');d.className='zoomv';d.innerHTML=`<img src="${src}" alt="" style="filter:${flt||'none'}">`;d.onclick=()=>d.remove();document.body.appendChild(d)}
document.addEventListener('click',e=>{const el=e.target;if(el&&el.classList&&el.classList.contains('zoomable')){e.stopPropagation();zoomImg(el.src,el.style.filter)}},true);
function title(){$('stage').innerHTML=`<div class="bg" style="background-image:url('${A('bg_village')}')"></div><div class="dock" style="top:auto">
 <div class="chip" style="align-self:stretch;text-align:center"><b style="font-size:20px;letter-spacing:.2em">渡鴉公會</b><br>天闕大陸・北境邊緣・暮簡村<br><span class="note">湖邊紙田的盡頭，有一座點著燭火的地方站。<br>村外的無字石碑群底下，有一座沒有人走完的地窖。<br>地面是活的，地底是死的。</span></div>
 <div class="bar4" style="grid-template-columns:${hadSave?'1fr 2fr':'1fr'}">${hadSave?'<button class="btn" id="bNew">重新開始</button>':''}<button class="btn primary" id="bStart">${hadSave?'繼續':'推開地方站的門'}</button></div>
 <div class="row" style="justify-content:center;margin:0"><button class="btn small" id="bAnn">公告${annSeen()?'':' ●'}</button></div>
 <p class="note" style="text-align:center;margin:0;text-shadow:0 1px 3px #000">${VER}・右上角 ♫ 可以打開音樂，🔊 是音量、遊玩報告、搬存檔和回到首頁<br>遊玩紀錄只存在這台裝置${hadSave&&localStorage.getItem(KEY)===null?'<br>v0.4 改了屬性和裝備系統：舊裝備換成了新的隨機裝備，積分上限調整為 400。':''}</p></div>`;
 $('bAnn').onclick=annShow;if(!annSeen())setTimeout(()=>{if(!modalOpen())annShow()},400);$('bStart').onclick=()=>{save();homePage()};if(hadSave)$('bNew').onclick=()=>modal(`<h2>重新開始？</h2><p>會清除這台裝置上的進度。</p><div class="row"><button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="S=fresh();save();closeModal();town('hall')">確定</button></div>`)}
window.addEventListener('resize',()=>{if(RUN&&!BAT&&!modalOpen())drawMap()});
res();title();
